import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.CpLciM8b.js";const f=JSON.parse('{"title":"Tracker issues for flakes","description":"","frontmatter":{},"headers":[],"relativePath":"guide/tracker.md","filePath":"guide/tracker.md","lastUpdated":1785920064000}'),r={name:"guide/tracker.md"};function i(n,e,h,l,c,d){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="tracker-issues-for-flakes" tabindex="-1">Tracker issues for flakes <a class="header-anchor" href="#tracker-issues-for-flakes" aria-label="Permalink to &quot;Tracker issues for flakes&quot;">​</a></h1><p>Detection used to end in a notification. Notifications are ephemeral — they fire once, they are not assignable, and nothing reflects it when the test recovers. A confirmed flake needs a durable home.</p><p>With this on, a test that stays flaky earns exactly one issue, which Flakemetry keeps up to date and closes itself when the test comes back.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>Two things are required, and the feature stays completely inert until both are present. An instance without credentials must never half-file a ticket.</p><ol><li><strong>A token on the instance.</strong> <code>FLAKEMETRY_TRACKER_TOKEN</code> — for GitHub, a fine-grained PAT with <strong>Issues: write</strong> on the repositories your projects point at.</li><li><strong>A repository on the project.</strong> Settings → Policy → Repository, as <code>owner/name</code>.</li></ol><p>Then set <strong>Open tracker issues for flakes</strong> to <em>On</em> in the same page.</p><h2 id="when-an-issue-is-opened" tabindex="-1">When an issue is opened <a class="header-anchor" href="#when-an-issue-is-opened" aria-label="Permalink to &quot;When an issue is opened&quot;">​</a></h2><p>When a test has been continuously flaky for <strong>Days flaky before opening an issue</strong> (default 3).</p><p>Persistence is measured from the start of the current flaky spell, not from the last failure. A test that flakes, recovers, and flakes again has not been broken for a week, and filing as though it had would be wrong in the direction of noise.</p><p>Deduplication is by <strong>test identity</strong>, not by run — so a rename or a file move does not produce a second ticket, for the same reason the <a href="/flakemetry/v/2026-09-30/concepts/test-identity">test identity</a> survives refactors. The database enforces one issue per test rather than trusting the sweep to remember.</p><h2 id="what-the-issue-contains" tabindex="-1">What the issue contains <a class="header-anchor" href="#what-the-issue-contains" aria-label="Permalink to &quot;What the issue contains&quot;">​</a></h2><p>The evidence, not a link to it — whoever picks the ticket up should not need a dashboard account to know what they are looking at:</p><ul><li>the flaky score and why it is scored that way, in reason codes</li><li>a flake-rate sparkline over the last 14 days</li><li>the most recent failure message</li><li>the AI root-cause summary, when one exists</li><li>the owner from CODEOWNERS</li><li>a dashboard link, when <code>FLAKEMETRY_DASHBOARD_URL</code> is set</li></ul><h2 id="while-it-is-open" tabindex="-1">While it is open <a class="header-anchor" href="#while-it-is-open" aria-label="Permalink to &quot;While it is open&quot;">​</a></h2><p>The sweep runs hourly and updates the issue body when the score has moved materially. It deliberately does <em>not</em> comment every hour — an issue that updates itself sixty times a week is one nobody reads.</p><h2 id="when-the-test-recovers" tabindex="-1">When the test recovers <a class="header-anchor" href="#when-the-test-recovers" aria-label="Permalink to &quot;When the test recovers&quot;">​</a></h2><p>After <strong>Days stable before closing it</strong> (default 7) the issue is closed with a comment.</p><p>If the test flakes again, the <strong>same issue reopens</strong> rather than a new one being filed, so the history of a recurring flake stays in one place.</p><h2 id="other-trackers" tabindex="-1">Other trackers <a class="header-anchor" href="#other-trackers" aria-label="Permalink to &quot;Other trackers&quot;">​</a></h2><p>The provider is behind an interface with GitHub as the first implementation, so GitLab and Jira can follow without touching the decision logic. That logic is pure and separate on purpose: a sweep that reasons about tickets while also talking to an API files duplicates the first time a request half-fails.</p>',21)])])}const p=t(r,[["render",i]]);export{f as __pageData,p as default};
